WITH unpacked AS (SELECT id, currency, tier_limits, discounts, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT currency, SUM(CASE WHEN currency = 'EUR' THEN entry_price ELSE 0 END) AS eur_entry_price, SIZE(COLLECT_SET(currency)) AS num_currencies FROM unpacked GROUP BY 1 ORDER BY eur_entry_price;
